using System;using System.IO;using System.Linq;using System.Threading;using System.Collections.Generic;using System.Drawing;using System.Globalization;using System.Windows.Forms;
namespace CodexUsage {
 public sealed class ChatUsageRow {public string Path,Title;public long? Tokens;public bool Failed;}
 public sealed class ChatUsageSnapshot {public readonly ChatUsageRow[] Rows;public readonly bool Loading;public ChatUsageSnapshot(ChatUsageRow[] rows,bool loading=false){Rows=rows;Loading=loading;}}
 public sealed class ChatUsageMonitor : IDisposable {
  sealed class Cached {public long Length;public DateTime Written;public long? Tokens;public bool Failed;}
  readonly string home;readonly Dictionary<string,Cached> cache=new Dictionary<string,Cached>(StringComparer.OrdinalIgnoreCase);readonly ManualResetEvent stop=new ManualResetEvent(false);readonly Thread worker;
  volatile ChatUsageSnapshot snapshot=new ChatUsageSnapshot(new ChatUsageRow[0],true);
  public ChatUsageSnapshot Snapshot {get{return snapshot;}}
  public ChatUsageMonitor(string home){this.home=home;worker=new Thread(Run){IsBackground=true,Name="Codex chat usage"};}
  public void Start(){worker.Start();}
  void Run(){try{do{Poll();}while(!stop.WaitOne(5000));}finally{stop.Dispose();}}
  void Poll(){var entries=TaskCatalog.All(home);var rows=new List<ChatUsageRow>();foreach(var entry in entries){if(stop.WaitOne(0))return;Cached item;cache.TryGetValue(entry.Path,out item);try{var file=new FileInfo(entry.Path);if(!file.Exists)throw new FileNotFoundException();if(item==null || item.Failed || item.Length!=file.Length || item.Written!=file.LastWriteTimeUtc){var usage=Reader.ReadTokens(entry.Path);item=new Cached{Length=file.Length,Written=file.LastWriteTimeUtc,Tokens=usage.Total};cache[entry.Path]=item;}}catch(IOException){item=new Cached{Tokens=item==null ? null : item.Tokens,Failed=true};cache[entry.Path]=item;}catch(UnauthorizedAccessException){item=new Cached{Tokens=item==null ? null : item.Tokens,Failed=true};cache[entry.Path]=item;}rows.Add(new ChatUsageRow{Path=entry.Path,Title=entry.Title,Tokens=item.Tokens,Failed=item.Failed});}
   var previous=snapshot;bool changed=previous.Loading || previous.Rows.Length!=rows.Count;for(int i=0;!changed && i<rows.Count;i++){var a=previous.Rows[i];var b=rows[i];changed=a.Path!=b.Path || a.Title!=b.Title || a.Tokens!=b.Tokens || a.Failed!=b.Failed;}if(changed)snapshot=new ChatUsageSnapshot(rows.ToArray());
   var retained=new HashSet<string>(entries.Select(e=>e.Path),StringComparer.OrdinalIgnoreCase);foreach(string key in cache.Keys.Where(k=>!retained.Contains(k)).ToArray())cache.Remove(key);
  }
  public void Dispose(){if(worker.IsAlive){stop.Set();worker.Join(3000);}else if(worker.ThreadState==ThreadState.Unstarted)stop.Dispose();}
 }
 public sealed class ChatUsagePanel : Panel {
  readonly Label quota=new Label(),caption=new Label();readonly ListView list=new ListView();readonly ToolTip hints=new ToolTip();ChatUsageSnapshot rendered;bool fittingColumns;
  public ChatUsagePanel(){Bounds=new Rectangle(20,68,360,176);Visible=false;quota.SetBounds(0,0,360,21);quota.Font=new Font("Segoe UI",9);caption.SetBounds(0,22,360,18);caption.Font=new Font("Segoe UI",8);list.SetBounds(0,42,360,134);list.Font=new Font("Segoe UI",8);list.View=View.Details;list.FullRowSelect=true;list.MultiSelect=false;list.ShowItemToolTips=true;list.HeaderStyle=ColumnHeaderStyle.Nonclickable;list.BorderStyle=BorderStyle.None;list.Columns.Add("채팅",218);list.Columns.Add("누적 토큰",122,HorizontalAlignment.Right);list.SizeChanged+=delegate{FitColumns();};Controls.Add(quota);Controls.Add(caption);Controls.Add(list);hints.SetToolTip(quota,"계정 전체 한도 사용률입니다. 채팅별 한도 사용률로 환산할 수 없습니다.");hints.SetToolTip(caption,"현재 PC의 채팅 기록 기준 · 최근 변경 순 · 스크롤로 전체 목록 확인");}
  void FitColumns(){if(fittingColumns || Disposing || IsDisposed || list.Disposing || list.Columns.Count<2)return;int available=list.ClientSize.Width;if(available<40)return;fittingColumns=true;try{int tokens=Math.Min(available/2,Math.Max(available/3,TextRenderer.MeasureText("9,999,999,999 *",list.Font).Width+12));list.Columns[0].Width=Math.Max(20,available-tokens-2);list.Columns[1].Width=tokens;}finally{fittingColumns=false;}}
  public void ApplyTheme(Palette p){BackColor=p.Surface;quota.ForeColor=p.Text;caption.ForeColor=p.Muted;list.BackColor=p.Surface;list.ForeColor=p.Text;}
  public void Render(AccountSnapshot account,ChatUsageSnapshot chats){var view=UsageView.Build(account,DateTimeOffset.Now);quota.Text=account.Period==null ? "계정 전체 한도 · 확인 대기" : "계정 전체 한도 사용 "+(100-account.Period.Remaining).ToString("0.#",CultureInfo.InvariantCulture)+"% · "+account.Period.Caption+(view.Stale ? " · 재확인 중" : "");caption.Text=chats.Loading ? "이 PC의 채팅 기록 확인 중…" : chats.Rows.Length==0 ? "이 PC에 저장된 채팅 기록 없음" : "이 PC · "+chats.Rows.Length+"개 채팅 · 최근순 · 5초마다 확인";if(Object.ReferenceEquals(rendered,chats))return;string selected=list.SelectedItems.Count==0 ? null : list.SelectedItems[0].Tag as string;int top=list.TopItem==null ? 0 : list.TopItem.Index;list.BeginUpdate();try{list.Items.Clear();foreach(var row in chats.Rows){var item=new ListViewItem(row.Title){Tag=row.Path,ToolTipText=row.Title+(row.Failed ? "\n읽기 실패 · 마지막 확인 값" : row.Tokens.HasValue ? "\n채팅에 기록된 누적 토큰" : "\n토큰 기록 없음")};item.SubItems.Add(row.Tokens.HasValue ? row.Tokens.Value.ToString("N0",CultureInfo.InvariantCulture)+(row.Failed ? " *" : "") : "—");list.Items.Add(item);if(row.Path==selected)item.Selected=true;}if(list.Items.Count>0)list.TopItem=list.Items[Math.Min(top,list.Items.Count-1)];}finally{list.EndUpdate();}FitColumns();rendered=chats;}
  protected override void Dispose(bool disposing){if(disposing)hints.Dispose();base.Dispose(disposing);}
 }
}
